#! /bin/bash

set -e # Exit on error

cd "$(dirname "$0")" # cd to this script dir

TMP=../css.rs.tmp
OUTPUT=../src/frontend/css.rs
ASSETS_FILE=../src/frontend/assets.rs

FOUND=false

function process_css_file() {
	local FILE=$1
	local OUTPUT=$2
	local INDEX=1

	while IFS= read -r CSS_LINE; do
		if [[ $CSS_LINE == *"impl Css::"* ]]; then
			local CLASS=${CSS_LINE%{*}
			local NAME=${CSS_LINE#*::}
			local INDEX="-f1"
			NAME=$(echo $NAME | cut -d ' ' -f1)
			CLASS=$(echo $CLASS | cut -d ' ' $INDEX)
			CLASS=${CLASS%::*} # Remove after ::
			CLASS=${CLASS%:*} # Remove after ::
			echo "    pub const $NAME: &str = \"${CLASS:1} \"; // Defined in ${1:3} line $INDEX" >> $OUTPUT
		fi
		INDEX=$((INDEX + 1))
	done < $1
}

while IFS= read -r LINE; do
	#echo "$LINE"

	if $FOUND ; then
		if [[ $LINE == *"];"* ]]; then
			echo "}" >> $TMP
			if cmp --silent -- "$TMP" "$OUTPUT"; then
				rm $TMP # Files are the same no change
			else
				mv $TMP $OUTPUT
			fi
			break
		else
			CUT=`echo "$LINE" | cut -d '"' -f 2`
			process_css_file "..$CUT" $TMP $OUTPUT
		fi
	else
		if [[ $LINE == *"pub const CSS_ASSETS: [Asset;"* ]]; then
			if [[ $LINE != *"= [asset!("* ]]; then # Check is the not the release array
				FOUND=true # Found start of CSS assets array
				echo "/* == Generated by: $(basename -- "$0") == */" > $TMP
				echo >> $TMP
				echo "#[non_exhaustive]" >> $TMP
				echo "pub struct Css; // CSS class names" >> $TMP
				echo >> $TMP
				echo "impl Css {" >> $TMP
			fi
		fi
	fi
done < $ASSETS_FILE